4.text:
$$
\begin{array}{l} \bar {S} _ {t} = \left[ \frac {A (1 - B)}{1 - A B - (1 - A) C} \right] S _ {t} P _ {t - N} \\ + \left[ \frac {(1 - A) (1 - C)}{1 - A B - (1 - A) C} \right] \bar {S} _ {t - 1} R _ {t - 1}. \\ \end{array}
$$

$$
\begin{array}{l} P _ {t} = \left[ \frac {[ 1 - B ] [ 1 - (1 - A) C ]}{1 - A B - (1 - A) C} \right] P _ {t - N} \\ + \left[ \frac {B (1 - A) (1 - C)}{1 - A B - (1 - A) C} \right] \frac {\bar {S} _ {t - 1}}{S _ {t}} R _ {t - 1}. \\ \end{array}
$$

$$
\begin{array}{l} R _ {t} = \left[ \frac {A C (1 - B)}{1 - A B - (1 - A) C} \right] \frac {S _ {t} P _ {t - N}}{\bar {S} _ {t - 1}} \\ + \left[ \frac {[ 1 - C ] [ 1 - A B ]}{1 - A B - (1 - A) C} \right] R _ {t - 1}. \\ \end{array}
$$

$$
P _ {t} = b \left(\bar {S} _ {t} - S _ {t}\right) + (1 - b) P _ {t - N}
$$

$$
\begin{array}{l} \bar {S} _ {t} = \left[ \frac {a (1 - b)}{1 - a b - (1 - a) c} \right] S _ {t} \\ + \left[ \frac {(1 - c) (1 - a)}{1 - a b - (1 - a) c} \right] \left[ \bar {S} _ {t - 1} + r _ {t - 1} \right] \\ + \left[ \frac {(1 - b) a}{1 - a b - (1 - a) c} \right] P _ {t - N}. \\ \end{array}
$$

5.text:
$$
\begin{array}{l} P _ {t} = \left[ \frac {a b (1 - b)}{1 - a b - (1 - a) c} - b \right] S _ {t} \\ + \left[ \frac {(1 - c) (1 - a) b}{1 - a b - (1 - a) c} \right] \left[ \bar {S} _ {t - 1} + r _ {t - 1} \right] \\ + \left[ \frac {a b (1 - b)}{1 - a b - (1 - a) c} + (1 - b) \right] P _ {t - N}. \\ \end{array}
$$

$$
\begin{array}{l} r _ {t} = \left[ \frac {a c (1 - b)}{1 - a b - (1 - a) c} \right] S _ {t} \\ + \left[ \frac {(1 - c) (1 - a) c}{1 - a b - (1 - a) c} - c \right] \bar {S} _ {t - 1} \\ + \left[ \frac {(1 - c) (1 - a) c}{1 - a b - (1 - a) c} + (1 - c) \right] r _ {t - 1} \\ + \left[ \frac {(1 - b) a c}{1 - a b - (1 - a) c} \right] P _ {t - N}. \\ \end{array}
$$

$$
\begin{array}{l} \bar {S} _ {t} = \left[ \frac {A (1 - B)}{1 - A B - (1 - A) c} \right] S _ {t} P _ {t - N} \\ + \left[ \frac {(1 - A) (1 - c)}{1 - A B - (1 - A) c} \right] \left[ \bar {S} _ {t - 1} + r _ {t - 1} \right]. \\ \end{array}
$$
